SELECT

FROM Instruments a WHERE 1 = 1

    AND a.instType = #{instType}


    AND a.instId = #{instId}


    AND a.uly = #{uly}


    AND a.category = #{category}


    AND a.baseCcy = #{baseCcy}


    AND a.quoteCcy = #{quoteCcy}


    AND a.settleCcy = #{settleCcy}


    AND a.ctVal = #{ctVal}


    AND a.ctMult = #{ctMult}


    AND a.ctValCcy = #{ctValCcy}


    AND a.optType = #{optType}


    AND a.stk = #{stk}


    AND a.listTime = #{listTime}


    AND a.expTime = #{expTime}


    AND a.lever = #{lever}


    AND a.tickSz = #{tickSz}


    AND a.lotSz = #{lotSz}


    AND a.minSz = #{minSz}


    AND a.ctType = #{ctType}


    AND a.alias = #{alias}


    AND a.state = #{state}


    AND a.maxLmtSz = #{maxLmtSz}


    AND a.maxMktSz = #{maxMktSz}


    AND a.maxTwapSz = #{maxTwapSz}


    AND a.maxIcebergSz = #{maxIcebergSz}


    AND a.maxTriggerSz = #{maxTriggerSz}


    AND a.maxStopSz = #{maxStopSz}


    AND a.tags = #{tags}


    AND a.detailDesc = #{detailDesc}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM Instruments a WHERE 1 = 1

    AND a.instType LIKE CONCAT('%',#{instType}, '%')


    AND a.instId LIKE CONCAT('%',#{instId}, '%')


    AND a.uly LIKE CONCAT('%',#{uly}, '%')


    AND a.category LIKE CONCAT('%',#{category}, '%')


    AND a.baseCcy LIKE CONCAT('%',#{baseCcy}, '%')


    AND a.quoteCcy LIKE CONCAT('%',#{quoteCcy}, '%')


    AND a.settleCcy LIKE CONCAT('%',#{settleCcy}, '%')


    AND a.ctVal = #{ctVal}


    AND a.ctMult = #{ctMult}


    AND a.ctValCcy LIKE CONCAT('%',#{ctValCcy}, '%')


    AND a.optType LIKE CONCAT('%',#{optType}, '%')


    AND a.stk = #{stk}


    AND a.listTime = #{listTime}


    AND a.expTime = #{expTime}


    AND a.lever = #{lever}


    AND a.tickSz = #{tickSz}


    AND a.lotSz = #{lotSz}


    AND a.minSz = #{minSz}


    AND a.ctType LIKE CONCAT('%',#{ctType}, '%')


    AND a.alias LIKE CONCAT('%',#{alias}, '%')


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.maxLmtSz = #{maxLmtSz}


    AND a.maxMktSz = #{maxMktSz}


    AND a.maxTwapSz = #{maxTwapSz}


    AND a.maxIcebergSz = #{maxIcebergSz}


    AND a.maxTriggerSz = #{maxTriggerSz}


    AND a.maxStopSz = #{maxStopSz}


    AND a.tags LIKE CONCAT('%',#{tags}, '%')


    AND a.detailDesc LIKE CONCAT('%',#{detailDesc}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
